import {LANGUAGES,escapeHTML as esc,compatibleEditions} from './core.js';
import {BRAZIL_STATES,dailyPassage} from './personalization.js';
const goals={faith:['pFaithGoal','hands'],calm:['pCalmGoal','leaf'],connection:['pConnectionGoal','people'],kindness:['pKindnessGoal','heart']};
const motivations={faith:'pFaithMotivation',calm:'pCalmMotivation',connection:'pConnectionMotivation',kindness:'pKindnessMotivation'};
const countries={BR:'pBrazil',PT:'Portugal',US:'United States',ES:'España',RU:'Россия',OTHER:'pOther'};
export function createProfile({t,ico,prefs,editions,setPrefs,render,focusMain,navigate,closeModal,toast,modal}){
 let profile=null,draft={},step=0,active=false,editing=false,busy=false,error='',loaded=false;
 const txt=k=>esc(t(k));
 async function request(body,method=body?'POST':'GET'){const response=await fetch('/api/profile',{method,headers:body?{'Content-Type':'application/json'}:{},...(body?{body:JSON.stringify(body)}:{}),signal:AbortSignal.timeout(10000)});if(!response.ok||!response.headers.get('content-type')?.includes('application/json'))throw Error('profile_unavailable');return response.json();}
 const blank=()=>({name:'',intent:'',city:'',region:'',country:'BR',email:'',notifications:false});
 function deferred(){try{return sessionStorage.getItem('still-onboarding-later')==='1';}catch{return false;}}
 function defer(){try{sessionStorage.setItem('still-onboarding-later','1');}catch{}}
 async function ready(){try{profile=(await request()).profile;loaded=true;if(!profile&&!deferred()){draft=blank();step=0;active=true;}}catch{loaded=false;}render();}
 function open(at=1){closeModal();if(!loaded){toast(t('pLoadError'));ready();return;}draft={...blank(),...profile};step=profile?at:1;active=true;editing=!!profile;error='';render();focusMain();}
 function field(key,label,{type='text',autocomplete='',required=false,max=80}={}){return `<div class="profile-field"><label for="profile-${key}">${txt(label)}</label><input id="profile-${key}" name="${key}" data-profile-field="${key}" type="${type}" autocomplete="${autocomplete}" maxlength="${max}" value="${esc(draft[key])}" ${required?'required':''}></div>`;}
 function countryName(id){return id==='BR'?t('pBrazil'):id==='OTHER'?t('pOther'):new Intl.DisplayNames([prefs().language],{type:'region'}).of(id);}
 function options(values,current,translate=true){return Object.entries(values).map(([id,label])=>`<option value="${id}" ${id===current?'selected':''}>${translate?txt(label):esc(label)}</option>`).join('');}
 function prefSelect(key,label,values){return `<div class="profile-field"><label for="onboard-${key}">${txt(label)}</label><select id="onboard-${key}" data-onboard-pref="${key}">${options(values,prefs()[key],false)}</select></div>`;}
 function preview(){return `<div class="onboarding-path">${[['journal','stepJournal'],['book','stepVerse'],['sprout','stepAction']].map(([icon,label],i)=>`<div><span>${ico(icon)}</span><strong>${txt(label)}</strong><small>0${i+1}</small></div>`).join('')}</div>`;}
 function content(){
  if(step===0)return `<div class="onboarding-art" aria-hidden="true"><div class="sun-halo"></div>${ico('sprout')}<span class="art-spark spark-one">✦</span><span class="art-spark spark-two">✧</span></div><div class="eyebrow">Still · ${txt('privateSpace')}</div><h1>${txt('pWelcome')}</h1><p class="onboarding-sub">${txt('pWelcomeSub')}</p>${preview()}`;
  if(step===1)return `<span class="onboard-symbol">${ico('pen')}</span><h1>${txt('pYourName')}</h1><p class="onboarding-sub">${txt('pNameSub')}</p>${field('name','pName',{autocomplete:'given-name',required:true,max:60})}<div class="profile-soft-note">${ico('lock')}<p>${txt('pPrivate')}</p></div>`;
  if(step===2)return `<span class="onboard-symbol">${ico('sprout')}</span><h1>${txt('pIntent')}</h1><p class="onboarding-sub">${txt('pIntentSub')}</p><div class="onboard-choices" role="group" aria-label="${txt('pIntent')}">${Object.entries(goals).map(([id,[label,icon]])=>`<button type="button" data-profile-goal="${id}" aria-pressed="${draft.intent===id}">${ico(icon)}<span>${txt(label)}</span><i>${draft.intent===id?ico('check'):''}</i></button>`).join('')}</div>`;
  if(step===3){const choices=compatibleEditions(editions(),prefs()),edition=choices.find(e=>e.id===prefs().edition);return `<span class="onboard-symbol">${ico('book')}</span><h1>${txt('pFaith')}</h1><p class="onboarding-sub">${txt('pFaithSub')}</p>${prefSelect('tradition','tradition',Object.fromEntries(['protestant','catholic','orthodox'].map(k=>[k,t(k)])))}${prefSelect('scriptureLanguage','scriptureLanguage',LANGUAGES)}${choices.length?prefSelect('edition','edition',Object.fromEntries(choices.map(e=>[e.id,e.name]))):`<p class="note-box">${txt('unavailable')}</p>`}${edition?`<p class="mini-note">${esc(edition.scope)}</p>`:''}`;}
  if(step===4)return `<span class="onboard-symbol">${ico('pin')}</span><h1>${txt('pLocation')}</h1><p class="onboarding-sub">${txt('pLocationSub')}</p><div class="profile-field"><label for="profile-country">${txt('pCountry')}</label><select id="profile-country" data-profile-field="country">${options(Object.fromEntries(Object.keys(countries).map(id=>[id,countryName(id)])),draft.country,false)}</select></div>${field('city','pCity',{autocomplete:'address-level2',required:true,max:80})}${draft.country==='BR'?`<div class="profile-field"><label for="profile-region">${txt('pRegion')}</label><select id="profile-region" data-profile-field="region" required><option value="">—</option>${options(Object.fromEntries(BRAZIL_STATES.map(x=>[x,x])),draft.region,false)}</select></div>`:field('region','pRegion',{autocomplete:'address-level1',max:80})}<p class="mini-note">${txt('pBrazilNote')}</p>`;
  if(step===5)return `<span class="onboard-symbol">${ico('sun')}</span><h1>${txt('pNotifications')}</h1><p class="onboarding-sub">${txt('pNotificationsSub')}</p>${field('email','pEmail',{type:'email',autocomplete:'email',max:254})}<label class="notification-consent"><input type="checkbox" data-profile-field="notifications" ${draft.notifications?'checked':''}><span>${txt('pConsent')}</span></label><div class="profile-soft-note">${ico('clock')}<p>${txt('pEmailPending')}</p></div>`;
  return `<div class="ready-mark">${ico('check')}</div><h1>${txt('pReady')}</h1><p class="onboarding-sub">${txt('pReadySub')}</p><div class="profile-summary"><strong>${esc(draft.name)}</strong><span>${ico('sprout')}${txt(goals[draft.intent]?.[0]||'pFaithGoal')}</span><span>${ico('book')}${txt(prefs().tradition)}</span><span>${ico('pin')}${esc([draft.city,draft.region,countryName(draft.country)].filter(Boolean).join(' · '))}</span><span>${ico('sun')}${draft.notifications?esc(draft.email):txt('pLater')}</span></div>${preview()}<p class="mini-note">${txt('pPrivate')}</p>`;
 }
 function view(){return `<div class="onboarding-shell"><header class="onboarding-top"><button class="icon-button" type="button" data-profile="${step?'back':'later'}" aria-label="${txt(step?'pBack':'close')}">${ico(step?'back':'close')}</button><span class="mobile-wordmark"><img src="./assets/mark.svg" alt="">still</span><label><span class="sr-only">${txt('interfaceLanguage')}</span><select aria-label="${txt('interfaceLanguage')}" data-onboard-pref="language">${options(LANGUAGES,prefs().language,false)}</select></label></header><div class="onboarding-progress" role="progressbar" aria-label="${txt('pStep')}" aria-valuemin="1" aria-valuemax="7" aria-valuenow="${step+1}">${Array.from({length:7},(_,i)=>`<i class="${i<=step?'filled':''}"></i>`).join('')}</div><form id="onboarding-form" novalidate><main class="onboarding-main" id="main" tabindex="-1"><div class="onboarding-counter">${txt('pStep')} ${step+1} / 7</div>${content()}<p id="profile-error" class="profile-error" role="alert">${esc(error)}</p></main><footer class="onboarding-bottom"><button class="primary full" type="submit" ${busy?'disabled':''}>${ico(step===6?'check':'arrow')}${txt(busy?'pSaving':step===0?'pBegin':step===6?(editing?'pFinish':'pStartJournal'):'pContinue')}</button><button class="text-button" type="button" data-profile="later" ${busy?'disabled':''}>${txt(editing?'cancel':'pLater')}</button></footer></form></div>`;}
 function validate(){const form=document.querySelector('#onboarding-form');if(!form.reportValidity()){error=t('pRequired');return false;}if(step===1&&!draft.name.trim()||step===4&&!draft.city.trim()){error=t('pRequired');return false;}if(step===2&&!goals[draft.intent]){error=t('pIntentRequired');return false;}if(step===5&&((draft.email.trim()&&!draft.notifications)||(draft.notifications&&!draft.email.trim()))){error=t('pEmailConsent');return false;}return true;}
 async function next(event){if(event.target.id!=='onboarding-form')return;event.preventDefault();if(busy)return;error='';if(!validate()){document.querySelector('#profile-error').textContent=error;return;}if(step<6){step++;render();focusMain();return;}busy=true;render();try{profile=(await request(draft)).profile;active=false;editing=false;toast(t('pSaved'));window.history.replaceState(null,'',location.pathname);navigate('journal','today');}catch{error=t('pSaveError');}finally{busy=false;render();focusMain();}}
 function input(el){const key=el.dataset.profileField;if(!key)return;draft[key]=el.type==='checkbox'?el.checked:el.value;}
 function change(el){if(el.dataset.onboardPref){setPrefs(el.dataset.onboardPref,el.value);render();return true;}if(el.dataset.profileField==='country'){draft.country=el.value;draft.region='';render();return true;}return false;}
 async function click(el){if(el.dataset.profileGoal){draft.intent=el.dataset.profileGoal;error='';render();document.querySelector(`[data-profile-goal="${draft.intent}"]`)?.focus();return true;}const action=el.dataset.profile;if(!action)return false;if(busy)return true;if(action==='edit'||action==='location')open(action==='location'?4:1);if(action==='back'){step=Math.max(0,step-1);error='';render();focusMain();}if(action==='later'){active=false;error='';defer();render();focusMain();}if(action==='delete')modal('pDeleteProfile',`<p>${txt('pDeleteConfirm')}</p><button class="primary full" data-profile="confirm-delete">${txt('pDeleteProfile')}</button>`);if(action==='confirm-delete'){el.disabled=true;try{await request({},'DELETE');profile=null;defer();closeModal();render();}catch{toast(t('pDeleteError'));el.disabled=false;}}return true;}
 function daily(){const p=dailyPassage(editions(),prefs());return `<section class="daily-welcome"><div class="daily-greeting">${txt('pHello')}${profile?.name?`, ${esc(profile.name)}`:''}<span>${esc(new Intl.DateTimeFormat(prefs().language,{month:'short',day:'numeric'}).format(new Date()))}</span></div><article class="daily-card"><div class="eyebrow">${ico('sun')}${txt(p?'pDaily':'pDailyMotivation')}</div>${p?`<blockquote lang="${p.language}">“${esc(p.text)}”</blockquote><a class="daily-reference" lang="${p.language}" href="${esc(p.sourceUrl)}" target="_blank" rel="noopener noreferrer">${esc(p.reference)} ${ico('external')}</a><span class="daily-edition">${esc(p.editionName)}</span>${p.editionId==='blivre'?`<small>${esc(p.attribution)} <a href="${esc(p.licenseUrl)}" target="_blank" rel="noopener noreferrer">CC BY 4.0</a></small>`:''}`:`<p class="daily-motivation">${txt(motivations[profile?.intent]||'pCalmMotivation')}</p><details><summary>${txt('edition')}</summary><p>${txt('unavailable')}</p><button class="text-button" data-action="settings">${txt('settings')}</button></details>`}${p?`<p class="daily-encouragement">${txt(motivations[profile?.intent]||'pCalmMotivation')}</p>`:''}</article></section>`;}
 function settings(){return `<div class="modal-section"><h3>${txt('pProfile')}</h3>${profile?`<p>${esc(profile.name)} · ${esc(profile.city)}</p>`:''}<button class="secondary" data-profile="edit">${txt('pEditProfile')}</button><p class="help">${txt('pPrivate')}</p>${profile?.notifications?`<p class="help">${txt('pEmailPending')}</p>`:''}${profile?`<button class="text-button danger" data-profile="delete">${txt('pDeleteProfile')}</button>`:''}</div>`;}
 document.addEventListener('submit',next);
 return {ready,view,daily,settings,click,input,change,get:()=>profile,isActive:()=>active};
}
